CREATE OR REPLACE PROCEDURE products_count(
	OUT total INTEGER
	)
AS 
BEGIN
	SELECT SUM(UnitsInStock) INTO total
	FROM products;
END;
/

CREATE OR REPLACE FUNCTION func_add_sql(
  num1 integer, 
  num2 integer
  ) 
RETURN integer
AS
BEGIN
RETURN num1 + num2;
END;
/

